package com.fream.back.domain.m15.repository;
@RequiredArgsConstructor
public class Xkh73RepositoryCustomImpl implements Xkh73RepositoryCustom {
    private final JPAQueryFactory queryFactory;
    private final QXkh73 notification = QXkh73.xkh73;
