    @Override
    public List<Xkh73> findByUserEmailAndCategory(String email, Xzv64 category) {
        return queryFactory
                .selectFrom(notification)
                .join(notification.user, user).fetchJoin()
                .where(
                        userEmailEq(email),
                        categoryEq(category)
                )
                .orderBy(notification.createdDate.desc())
                .fetch();
    }
