    public List<Xkh73> findByUserEmailAndType(String email, Xkh73Type type) {
        return queryFactory
                .selectFrom(notification)
                .join(notification.user, user).fetchJoin()
                .where(
                        userEmailEq(email),
                        typeEq(type)
                )
                .orderBy(notification.createdDate.desc())
                .fetch();
    }
    @Override
    public Page<Xkh73> findByUserEmailAndIsRead(String email, boolean isRead, Pageable pageable) {
        List<Xkh73> content = queryFactory
                .selectFrom(notification)
                .join(notification.user, user).fetchJoin()
                .where(
                        userEmailEq(email),
                        isReadEq(isRead)
                )
                .orderBy(getOrderSpecifiers(pageable).toArray(OrderSpecifier[]::new))
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();
        JPAQuery<Long> countQuery = queryFactory
                .select(notification.count())
                .from(notification)
                .join(notification.user, user)
                .where(
                        userEmailEq(email),
                        isReadEq(isRead)
                );
        return PageableExecutionUtils.getPage(content, pageable, countQuery::fetchOne);
    }
    @Override
    public Page<Xkh73> findByUserEmailAndCategoryAndIsRead(
            String email, Xzv64 category, boolean isRead, Pageable pageable) {
        List<Xkh73> content = queryFactory
                .selectFrom(notification)
                .join(notification.user, user).fetchJoin()
                .where(
                        userEmailEq(email),
                        categoryEq(category),
                        isReadEq(isRead)
                )
                .orderBy(getOrderSpecifiers(pageable).toArray(OrderSpecifier[]::new))
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();
        JPAQuery<Long> countQuery = queryFactory
                .select(notification.count())
                .from(notification)
                .join(notification.user, user)
                .where(
                        userEmailEq(email),
                        categoryEq(category),
                        isReadEq(isRead)
                );
        return PageableExecutionUtils.getPage(content, pageable, countQuery::fetchOne);
    }
    @Override
    public Page<Xkh73> findByUserEmailAndTypeAndIsRead(
            String email, Xkh73Type type, boolean isRead, Pageable pageable) {
        List<Xkh73> content = queryFactory
                .selectFrom(notification)
                .join(notification.user, user).fetchJoin()
                .where(
                        userEmailEq(email),
                        typeEq(type),
                        isReadEq(isRead)
                )
                .orderBy(getOrderSpecifiers(pageable).toArray(OrderSpecifier[]::new))
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();
        JPAQuery<Long> countQuery = queryFactory
                .select(notification.count())
                .from(notification)
                .join(notification.user, user)
                .where(
                        userEmailEq(email),
                        typeEq(type),
                        isReadEq(isRead)
                );
        return PageableExecutionUtils.getPage(content, pageable, countQuery::fetchOne);
    }
    @Override
    public List<Xkh73> findAllByUserEmail(String email) {
        return queryFactory
                .selectFrom(notification)
                .join(notification.user, user).fetchJoin()
                .where(userEmailEq(email))
                .orderBy(notification.createdDate.desc())
                .fetch();
    }
    private BooleanExpression userEmailEq(String email) {
        return email != null ? user.email.eq(email) : null;
    }
    private BooleanExpression categoryEq(Xzv64 category) {
        return category != null ? notification.category.eq(category) : null;
    }
    private BooleanExpression typeEq(Xkh73Type type) {
        return type != null ? notification.type.eq(type) : null;
    }
    private BooleanExpression isReadEq(Boolean isRead) {
        return isRead != null ? notification.isRead.eq(isRead) : null;
    }
    private List<OrderSpecifier<?>> getOrderSpecifiers(Pageable pageable) {
        List<OrderSpecifier<?>> orders = new ArrayList<>();
        if (pageable.getSort().isEmpty()) {
            orders.add(new OrderSpecifier<>(Order.DESC, notification.createdDate));
            return orders;
        }
        for (Sort.Order order : pageable.getSort()) {
            Order direction = order.getDirection().isAscending() ? Order.ASC : Order.DESC;
            switch (order.getProperty()) {
                case "createdDate":
                    orders.add(new OrderSpecifier<>(direction, notification.createdDate));
                    break;
                case "category":
                    orders.add(new OrderSpecifier<>(direction, notification.category));
                    break;
                case "type":
                    orders.add(new OrderSpecifier<>(direction, notification.type));
                    break;
                case "isRead":
                    orders.add(new OrderSpecifier<>(direction, notification.isRead));
                    break;
                default:
                    orders.add(new OrderSpecifier<>(Order.DESC, notification.createdDate));
                    break;
            }
        }
        return orders;
    }
