    ) {
        if (colorIds == null || colorIds.isEmpty()) {
            return new PageImpl<>(Collections.emptyList(), pageable, 0);
        }


        QXkr46 product = QXkr46.xkr46;
        QXfp92 productColor = QXfp92.xfp92;
